"""Plain-English insights, generated by simple if/else rules.

Each insight is a dict:
    id, area (savings | spending | emergency | debt | portfolio),
    severity (critical | warning | info | positive), title, detail, action
"""
from __future__ import annotations

from .analysis import Snapshot, category_breakdown
from .categories import ASSET_TYPE_LABELS, WANT_CATEGORIES

SEVERITY_ORDER = {"critical": 0, "warning": 1, "info": 2, "positive": 3}


def _pct(value: float) -> str:
    return f"{value * 100:.0f}%"


def generate_insights(s: Snapshot, portfolio: dict, currency: str = "USD") -> list[dict]:
    def money(amount: float) -> str:
        return f"{amount:,.0f} {currency}"

    out: list[dict] = []

    def add(id_, area, severity, title, detail, action=None):
        out.append(
            {"id": id_, "area": area, "severity": severity, "title": title,
             "detail": detail, "action": action}
        )

    if s.months == 0:
        add("no-data", "savings", "info", "Nothing to analyse yet",
            "Add some income and expense records and the score and insights will appear.",
            "Add a transaction")
        return out

    # ---- Savings ------------------------------------------------------------
    rate = s.savings_rate
    if rate is None:
        add("savings-no-income", "savings", "info", "No income recorded",
            "A savings rate needs income. Add your salary or other income.", "Add income")
    elif rate < 0:
        add("savings-negative", "savings", "critical", "You are spending more than you earn",
            f"Expenses exceed income by about {money(-s.avg_savings)} a month.",
            "Review your largest expense categories first")
    elif rate < 0.10:
        gap = max(0.0, 0.20 * s.avg_income - s.avg_savings)
        add("savings-low", "savings", "warning", f"Savings rate is only {_pct(rate)}",
            f"Saving 20% of income is a common target. That is about {money(gap)} more each month.",
            "Pick one category to trim")
    elif rate < 0.20:
        gap = max(0.0, 0.20 * s.avg_income - s.avg_savings)
        add("savings-ok", "savings", "info", f"Saving {_pct(rate)} of income",
            f"Close to the 20% benchmark. About {money(gap)} more a month would get you there.",
            "Automate a transfer on payday")
    else:
        add("savings-good", "savings", "positive", f"Saving {_pct(rate)} of income",
            "You are at or above the 20% benchmark. Keep it steady.")

    # ---- Spending -----------------------------------------------------------
    if s.income_total > 0:
        wants_share = s.wants_total / s.income_total
        wants = [c for c in category_breakdown(s) if c["category"] in WANT_CATEGORIES]
        if wants_share > 0.30:
            top = wants[0]["category"] if wants else "discretionary spending"
            add("wants-high", "spending", "warning",
                f"Wants take {_pct(wants_share)} of income",
                f"The guide is 30% or less. {top} is the biggest want category.",
                f"Set a monthly limit for {top}" if wants else None)
        else:
            add("wants-ok", "spending", "positive",
                f"Wants are {_pct(wants_share)} of income",
                "Discretionary spending is inside the 30% guide.")

        housing = s.expense_by_category.get("Housing", 0.0)
        if housing / s.income_total > 0.35:
            add("housing-high", "spending", "warning",
                f"Housing is {_pct(housing / s.income_total)} of income",
                "Housing above about 35% of income leaves little room for saving.",
                "Check if rent or utilities can be reduced")

    if s.expense_total > 0:
        top_cat = max(s.expense_by_category.items(), key=lambda kv: kv[1])
        share = top_cat[1] / s.expense_total
        if top_cat[0] != "Housing" and share > 0.25:
            add("top-category", "spending", "info",
                f"{top_cat[0]} is {_pct(share)} of all spending",
                "One category dominating your spending is the best place to look for savings.")

    if len(s.monthly_expenses) >= 3:
        *earlier, (_, latest) = s.monthly_expenses
        average = sum(v for _, v in earlier) / len(earlier)
        if average > 0:
            change = latest / average - 1
            if change >= 0.15:
                add("spend-rising", "spending", "warning",
                    f"Spending rose {_pct(change)} last month",
                    f"Last month's expenses were {money(latest)} against a usual {money(average)}.",
                    "Look for one-off costs versus a new habit")
            elif change <= -0.10:
                add("spend-falling", "spending", "positive",
                    f"Spending fell {_pct(-change)} last month",
                    f"Last month's expenses were {money(latest)} against a usual {money(average)}.")

    # ---- Emergency fund -----------------------------------------------------
    if s.avg_expenses > 0:
        covered = s.cash_value / s.avg_expenses
        shortfall = max(0.0, 6 * s.avg_expenses - s.cash_value)
        if covered < 1:
            add("emergency-critical", "emergency", "critical",
                f"Cash covers only {covered:.1f} months of expenses",
                f"Six months would be about {money(6 * s.avg_expenses)}. You are {money(shortfall)} short.",
                "Build a starter buffer of one month first")
        elif covered < 3:
            add("emergency-low", "emergency", "warning",
                f"Cash covers {covered:.1f} months of expenses",
                f"Aim for 3 to 6 months. Six months is about {money(6 * s.avg_expenses)}.",
                "Direct new savings to cash before investing more")
        elif covered < 6:
            add("emergency-ok", "emergency", "info",
                f"Cash covers {covered:.1f} months of expenses",
                "A decent cushion. Six months earns full points.")
        else:
            add("emergency-good", "emergency", "positive",
                f"Cash covers {covered:.1f} months of expenses",
                "Your emergency fund meets the six-month target.")

    # ---- Debt ---------------------------------------------------------------
    if s.income_total > 0 and s.debt_total > 0:
        ratio = s.debt_total / s.income_total
        if ratio > 0.36:
            add("debt-critical", "debt", "critical", f"Debt payments are {_pct(ratio)} of income",
                "Above about 36% is considered a heavy load.", "Look at refinancing or paying the costliest loan first")
        elif ratio > 0.15:
            add("debt-high", "debt", "warning", f"Debt payments are {_pct(ratio)} of income",
                "Under 10% earns full points.", "Consider extra payments on the highest-interest loan")

    # ---- Portfolio ----------------------------------------------------------
    holdings = s.investments
    total = s.investment_value
    if not holdings or total <= 0:
        add("portfolio-empty", "portfolio", "info", "No investments recorded",
            "Add your stocks, funds or other holdings to see allocation and concentration.",
            "Add a holding")
    else:
        top = max(holdings, key=lambda h: h.value)
        top_share = top.value / total
        biggest_class = portfolio["allocation"][0] if portfolio["allocation"] else None
        classes = len({h.asset_type for h in holdings})
        flagged = False

        if top_share > 0.30:
            flagged = True
            add("holding-concentrated", "portfolio", "warning",
                f"{top.name} is {_pct(top_share)} of your investments",
                "A single holding above 30% makes the portfolio sensitive to one price.",
                "Rebalance new contributions toward other holdings")
        if biggest_class and biggest_class["weight"] > 0.60:
            flagged = True
            label = ASSET_TYPE_LABELS.get(biggest_class["asset_type"], biggest_class["asset_type"])
            add("class-concentrated", "portfolio", "warning",
                f"{label} are {_pct(biggest_class['weight'])} of your investments",
                "More than 60% in one asset type is a concentrated bet.",
                "Spread across at least three asset types")
        if classes < 3:
            flagged = True
            add("few-classes", "portfolio", "info",
                f"Only {classes} asset type{'s' if classes != 1 else ''} held",
                "Mixing stocks, funds, bonds and gold usually smooths out the ups and downs.")
        if not flagged:
            add("portfolio-spread", "portfolio", "positive", "Portfolio is well spread",
                f"{classes} asset types and no holding above 30%.")

        for h in holdings:
            if h.invested > 0 and (h.value - h.invested) / h.invested <= -0.15:
                loss = (h.invested - h.value) / h.invested
                add(f"loser-{h.id}", "portfolio", "info",
                    f"{h.name} is down {_pct(loss)} from your buy price",
                    "Check that the manually entered price is up to date before acting on it.")

        gain_pct = portfolio["gain_pct"]
        add("portfolio-gain", "portfolio", "positive" if gain_pct >= 0 else "info",
            f"Portfolio is {'up' if gain_pct >= 0 else 'down'} {abs(gain_pct):.1f}% on cost",
            "Based on the current prices you entered. These are not live market prices.")

    out.sort(key=lambda i: SEVERITY_ORDER[i["severity"]])
    return out
